<template>
  <div class="page-alert-silences">
    <div class="page-header">
      <h2>{{ t('alerts.silences.title') }}</h2>
      <el-button type="primary" @click="onCreate">{{ t('alerts.silences.createSilence') }}</el-button>
    </div>

    <el-card>
      <el-table v-loading="loading" :data="pagedSilences" stripe>
        <el-table-column prop="id" label="ID" width="80" />
        <el-table-column :label="t('alerts.silences.matchers')" min-width="200">
          <template #default="{ row }">
            <CodeEditor :model-value="formatMatchers(row.matchers)" :rows="3" disabled />
          </template>
        </el-table-column>
        <el-table-column prop="starts_at" :label="t('alerts.silences.startsAt')" width="170" />
        <el-table-column prop="ends_at" :label="t('alerts.silences.endsAt')" width="170" />
        <el-table-column prop="comment" :label="t('alerts.silences.comment')" min-width="140" show-overflow-tooltip />
        <el-table-column :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="isActive(row) ? 'success' : 'info'" size="small">
              {{ isActive(row) ? t('alerts.silences.active') : t('alerts.silences.expired') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="120" fixed="right">
          <template #default="{ row }">
            <ConfirmButton
              :title="t('alerts.silences.confirmDelete')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </el-table>

      <div class="pagination-bar">
        <el-pagination
          v-model:current-page="page"
          v-model:page-size="pageSize"
          :page-sizes="[10, 20, 50]"
          :total="silences.length"
          layout="total, sizes, prev, pager, next"
          background
        />
      </div>
    </el-card>

    <el-dialog v-model="dialogVisible" :title="t('alerts.silences.dialogTitle')" width="600px" :close-on-click-modal="false">
      <el-form ref="formRef" :model="form" :rules="rules" label-width="100px">
        <el-form-item :label="t('alerts.silences.matchers')" prop="matchers">
          <JsonEditor v-model="form.matchers" :rows="6" placeholder='{"alertname": "cpu"}' />
        </el-form-item>
        <el-form-item :label="t('alerts.silences.effectiveFrom')" prop="starts_at">
          <el-date-picker
            v-model="form.starts_at"
            type="datetime"
            :placeholder="t('alerts.silences.startsAt')"
            value-format="YYYY-MM-DDTHH:mm:ss"
          />
        </el-form-item>
        <el-form-item :label="t('alerts.silences.effectiveUntil')" prop="ends_at">
          <el-date-picker
            v-model="form.ends_at"
            type="datetime"
            :placeholder="t('alerts.silences.endsAt')"
            value-format="YYYY-MM-DDTHH:mm:ss"
          />
        </el-form-item>
        <el-form-item :label="t('alerts.silences.comment')">
          <el-input v-model="form.comment" type="textarea" :rows="2" :placeholder="t('common.optional')" />
        </el-form-item>
      </el-form>

      <template #footer>
        <el-button @click="dialogVisible = false">{{ t('common.cancel') }}</el-button>
        <el-button type="primary" :loading="submitting" @click="onSubmit">{{ t('common.create') }}</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  createAlertSilence,
  deleteAlertSilence,
  getAlertSilences,
  type AlertSilenceRead,
} from '@/api/alertSilences'
import JsonEditor from '@/components/common/JsonEditor.vue'
import CodeEditor from '@/components/common/CodeEditor.vue'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()

const silences = ref<AlertSilenceRead[]>([])
const loading = ref(false)
const page = ref(1)
const pageSize = ref(10)
const dialogVisible = ref(false)
const submitting = ref(false)
const formRef = ref<FormInstance>()

const form = ref<{
  matchers: Record<string, unknown>
  starts_at: string
  ends_at: string
  comment: string
}>({
  matchers: {},
  starts_at: '',
  ends_at: '',
  comment: '',
})

const rules: FormRules = {
  matchers: [{ required: true, message: () => t('alerts.silences.matchersRequired'), trigger: 'blur' }],
  starts_at: [{ required: true, message: () => t('alerts.silences.startsAtRequired'), trigger: 'change' }],
  ends_at: [{ required: true, message: () => t('alerts.silences.endsAtRequired'), trigger: 'change' }],
}

const pagedSilences = computed(() => {
  const start = (page.value - 1) * pageSize.value
  return silences.value.slice(start, start + pageSize.value)
})

function isActive(row: AlertSilenceRead): boolean {
  const now = new Date().toISOString()
  return row.starts_at <= now && row.ends_at >= now
}

function formatMatchers(matchers: Record<string, unknown>): string {
  return JSON.stringify(matchers, null, 2)
}

async function loadSilences() {
  loading.value = true
  try {
    silences.value = await getAlertSilences()
  } catch (error) {
    showError(error, t('alerts.silences.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onCreate() {
  form.value = {
    matchers: {},
    starts_at: '',
    ends_at: '',
    comment: '',
  }
  dialogVisible.value = true
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    await createAlertSilence({
      matchers: form.value.matchers,
      starts_at: new Date(form.value.starts_at).toISOString(),
      ends_at: new Date(form.value.ends_at).toISOString(),
      comment: form.value.comment || undefined,
    })
    ElMessage.success(t('alerts.silences.created'))
    dialogVisible.value = false
    loadSilences()
  } catch (error) {
    showError(error, t('alerts.silences.createFailed'))
  } finally {
    submitting.value = false
  }
}

async function onDelete(row: AlertSilenceRead) {
  try {
    await deleteAlertSilence(row.id)
    ElMessage.success(t('alerts.silences.deleted'))
    loadSilences()
  } catch (error) {
    showError(error, t('alerts.silences.deleteFailed'))
  }
}

onMounted(() => {
  loadSilences()
})
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}

.pagination-bar {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}
</style>
