import apiClient from './client'

export interface AlertSilenceRead {
  id: number
  matchers: Record<string, unknown>
  starts_at: string
  ends_at: string
  comment?: string | null
  created_by?: number | null
  created_at: string
}

export interface AlertSilenceCreate {
  matchers: Record<string, unknown>
  starts_at: string
  ends_at: string
  comment?: string
}

export async function getAlertSilences(): Promise<AlertSilenceRead[]> {
  const response = await apiClient.get<AlertSilenceRead[]>('/v1/alert-silences')
  return response.data
}

export async function createAlertSilence(data: AlertSilenceCreate): Promise<AlertSilenceRead> {
  const response = await apiClient.post<AlertSilenceRead>('/v1/alert-silences', data)
  return response.data
}

export async function deleteAlertSilence(id: number): Promise<void> {
  await apiClient.delete(`/v1/alert-silences/${id}`)
}
